  { t: '$HASP395 WLDPAY1 ENDED - RC=0000', c: 'done' }
];
function add(spec){
  var d = document.createElement('div');
  d.className = 'trx1-job-submit-ln trx1-job-submit-' + spec.c;
  d.textContent = spec.t;
  log.appendChild(d);
  return d;
}
function elapsed(){
  if (rc) rc.textContent = 'ELAPSED 00:' + ('0' + sec).slice(-2);
}
