    if (rc){ rc.className = 'trx1-job-submit-rc'; rc.textContent = ''; }
    var first = { t: '', c: lines[0].c };
    var node = add(first);
    var full = lines[0].t, n = 0;
    (function typ(){
      n++; node.textContent = full.slice(0, n);
      if (n < full.length) t = setTimeout(typ, 42);
      else {
        clock = setInterval(function(){ sec++; elapsed(); }, 700);
        elapsed();
        t = setTimeout(function(){ stream(1); }, 520);
      }
    })();
  }
  function stream(i){
    if (i >= lines.length){
      clearInterval(clock);
      if (rc){ rc.textContent = 'RC=0000'; rc.className = 'trx1-job-submit-rc trx1-job-submit-rcok'; }
      t = setTimeout(start, 3000);
