  var bd = r.querySelector('.trx1-dataset-list-bd');
  var pc = r.querySelector('.trx1-dataset-list-pct');
  if (bf) bf.textContent = rep(f, '█');
  if (bd) bd.textContent = rep(CELLS - f, '░');
  if (pc) pc.textContent = pct;
}
function fill(r, target, done){
  var v = 0;
  var iv = setInterval(function(){
    v += Math.max(1, Math.round(target / 12));
    if (v >= target){ v = target; clearInterval(iv); if (done) done(); }
    draw(r, v);
  }, 38);
}
