  { x: '', clk: 0, w: '', ins: '', lock: 0, n: 'READY — KEYBOARD UNLOCKED', c: '' },
  { x: 'X', clk: 1, w: ' SYSTEM', ins: '', lock: 1, n: 'HOST BUSY — INPUT INHIBITED', c: 'busy' },
  { x: 'X', clk: 0, w: ' -F', ins: '', lock: 1, n: 'OPERATOR ERROR — PRESS RESET', c: 'err' },
  { x: '', clk: 0, w: '', ins: '^', lock: 0, n: 'INSERT MODE ON', c: '' },
  { x: 'X', clk: 0, w: ' ( )', ins: '', lock: 1, n: 'SESSION RECONNECTING', c: 'busy' }
];
var si = 0, gi = 0, col = 31, t = null, spin = null, tickr = null;
function apply(s){
  if (x) x.textContent = s.x;
  if (w) w.textContent = s.w;
  if (ins) ins.textContent = s.ins;
  if (note){
    note.className = 'trx1-sysind-line-note' + (s.c ? ' trx1-sysind-line-n-' + s.c : '');
    note.textContent = s.n;
  }
  if (scr){
    if (s.lock) scr.classList.add('trx1-sysind-line-lock');
    else scr.classList.remove('trx1-sysind-line-lock');
  }
  if (clk) clk.textContent = s.clk ? glyph[gi] : '';
  if (spin){ clearInterval(spin); spin = null; }
  if (s.clk && !reduce){
    spin = setInterval(function(){ gi = (gi + 1) % 4; if (clk) clk.textContent = glyph[gi]; }, 130);
  }
}
if (reduce){
  apply(states[1]);
  if (clk) clk.textContent = glyph[0];
} else {
  tickr = setInterval(function(){
    col = col >= 78 ? 22 : col + 1;
    if (pos) pos.textContent = '09/' + ('00' + col).slice(-3);
  }, 520);
  (function cycle(){
    apply(states[si % states.length]);
    si++;
    t = setTimeout(cycle, 2400);
  })();
}
